const QS={i:0,on:false,raf:0,t0:0,after:null};
const QSL=[
 {t:'Objetivo',d:'Defiende el <b>núcleo</b>. Los enemigos salen por los extremos del camino y van hacia él; si llegan, pierdes vida. Si la vida llega a 0, pierdes la partida.'},
 {t:'Piezas',h:['portal','fork'],d:'Cada ronda colocas una pieza que alarga el camino; puedes <b>girarla</b> antes de colocarla. Por los extremos libres del camino salen los enemigos: son los <b>portales</b> por donde salen los enemigos.'},
 {t:'Torres',h:['build'],d:'Construye torres junto al camino: disparan solas a los enemigos a su alcance. Con oro puedes <b>mejorarlas</b>; a Nv 4 eliges una especialización.'},
 {t:'Casillas especiales',h:['tile'],d:'Algunas piezas traen casillas de colores. La torre que pongas encima gana su bonus: más daño, más alcance, más velocidad…'},
 {t:'Héroe',h:['hero'],d:'Tu héroe lucha en el camino y bloquea enemigos. Puedes moverlo en cualquier momento, también durante la oleada, pulsando su retrato.'},
 {t:'Cofres y eventos',h:['chest','evtile'],d:'Si tu camino llega a un <b>cofre</b>, eliges una reliquia. Si llega a una casilla de <b>evento</b>, ocurrirá algo y tendrás que decidir.'},
 {t:'Daño y defensas',h:['armor','mres'],d:'El daño <b>físico</b> lo reduce la <b>armadura</b>; el <b>mágico</b>, la <b>resistencia mágica</b>. Combina tipos de daño según los enemigos que vengan.'},
 {t:'Personaliza tu juego',h:['optsx'],d:OPTTXT,mock:1}];
function openQuick(after){QS.i=0;QS.mx=0;QS.on=true;QS.after=after||null;QS.t0=performance.now();renderQuick();cancelAnimationFrame(QS.raf);const lp=t=>{if(!QS.on)return;drawQuick(t);QS.raf=requestAnimationFrame(lp);};QS.raf=requestAnimationFrame(lp);}
function renderQuick(){const s=QSL[QS.i];QS.mx=Math.max(QS.mx||0,QS.i);$('msetup').innerHTML=`<div class="qsw"><small>Tutorial rápido · ${QS.i+1}/${QSL.length}</small><h3>${s.t}</h3>${s.mock?optsMock():'<canvas id="qsc" width="420" height="220"></canvas>'}<p class="qsd">${s.d}</p>`+
 `<div class="qsn"><button data-a="qprev"${QS.i?'':' disabled'}>‹ Anterior</button><span class="hdots">${QSL.map((_,i)=>`<span class="qdot${i===QS.i?' on':''}"></span>`).join('')}</span>${QS.i<QSL.length-1?'<button data-a="qnext">Siguiente ›</button>':'<button class="go" data-a="qend">¡A jugar!</button>'}</div><button data-a="qskip" class="qsk">Saltar</button></div>`;$('menu').classList.add('setup');QS.t0=performance.now();}
// las pistas que ya explican las diapositivas vistas no se repiten en la partida
function quickSeen(){for(let i=0;i<=(QS.mx||0)&&i<QSL.length;i++)for(const id of QSL[i].h||[])HSEEN[id]=1;try{localStorage.setItem('rt-hints',JSON.stringify(HSEEN));}catch(e){}}
function closeQuick(){QS.on=false;cancelAnimationFrame(QS.raf);}
// mini-escenas dibujadas a mano (simples, en bucle)
function drawQuick(now){const cv=document.getElementById('qsc');if(!cv)return;const c=cv.getContext('2d'),W=420,H=220,t=((now-QS.t0)/1000);c.clearRect(0,0,W,H);c.fillStyle='#2e3441';c.fillRect(0,0,W,H);
 const path=(pts,w)=>{c.strokeStyle='#a8854a';c.lineWidth=w||28;c.lineCap='square';c.lineJoin='miter';c.beginPath();pts.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.stroke();};
 const dot=(x,y,r,col)=>{c.fillStyle=col;c.beginPath();c.arc(x,y,r,0,7);c.fill();};
 const core=(x,y)=>{c.fillStyle='#3dd6c4';c.fillRect(x-16,y-16,32,32);};
 const txt=(s,x,y,col,sz)=>{c.font='bold '+(sz||14)+'px sans-serif,"Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji"';c.textAlign='center';c.textBaseline='middle';c.lineWidth=3;c.strokeStyle='#14161c';c.strokeText(s,x,y);c.fillStyle=col||'#fff';c.fillText(s,x,y);};
 const tower=(x,y,ic,col)=>{dot(x,y,17,col||'#e8b04a');c.font='18px sans-serif,"Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji"';c.textAlign='center';c.textBaseline='middle';c.fillText(ic,x,y+1);};
 const lerp=(a,b,k)=>a+(b-a)*k,i=QS.i;
 if(i===0){path([[20,110],[400,110]]);core(390,110);for(let k=0;k<4;k++){const p=((t*.25+k*.25)%1);dot(lerp(20,380,p),110,8,'#e05a5a');if(p>.97)txt('−1 ❤️',380,70,'#ff6b5e',16);}txt('❤️ 20',60,30,'#ff8a8a',16);}
 if(i===1){const s=14,B=P*s,ox=W/2-B,oy=(H-B)/2+6;
  const blk=(p,x,y,tint)=>{for(let r=0;r<P;r++)for(let q=0;q<P;q++){const ch=p[r][q],cv0=cellOf(ch);c.fillStyle=cv0===2?'#a8854a':'#2c3a2f';c.fillRect(x+q*s,y+r*s,s,s);if(cv0===3)drawObs(c,ch,x+q*s,y+r*s,s);else if(cv0===1)drawSolar(c,x+q*s,y+r*s,s);if(ch==='C'){c.fillStyle='#3dd6c4';c.fillRect(x+q*s-s*.3,y+r*s-s*.3,s*1.6,s*1.6);}}c.strokeStyle='rgba(0,0,0,.35)';c.lineWidth=1;c.strokeRect(x+.5,y+.5,B-1,B-1);if(tint){c.fillStyle=tint;c.fillRect(x,y,B,B);c.strokeStyle=tint.replace(/[\d.]+\)$/,'1)');c.lineWidth=2;c.strokeRect(x+1,y+1,B-2,B-2);}};
  // la Esquina real: busca la rotación que conecta con la salida del núcleo (entrada por la izquierda, fila 3) y empieza dos giros antes
  const E0=PIECES.find(p=>p.n==='Esquina').p,rs=[E0,rot(E0),rot(rot(E0)),rot(rot(rot(E0)))],ok=rs.findIndex(p=>p[3][0]==='.'),st=(ok+2)%4;
  const T0=t%6.4,k=T0<1.4?0:T0<2.8?1:2,pc=rs[(st+k)%4],placed=T0>=4.2,lift=placed?0:T0>=3.4?(1-(T0-3.4)/.8)*14:14;
  blk(BASE,ox,oy,null);blk(pc,ox+B,oy-lift,placed?null:k<2?'rgba(224,72,72,.38)':'rgba(80,200,110,.38)');
  txt(placed?'Colocada':k<2?(T0%1.4<.7&&k>0?'↻ Girar':'No encaja'):'¡Encaja!',ox+B+B/2,oy-24,placed?'#ffd75a':k<2?'#ff7a6e':'#7fe08f',14);
  if(placed){const p=Math.min(1,(T0-4.2)/2),ex=pc.findIndex((row,r)=>r===P-1&&row.includes('.'))>=0?'S':'N',cx=ox+B+3.5*s,cy=oy+3.5*s,sy=ex==='S'?oy+B:oy,L1=Math.abs(cy-sy),L2=cx-(ox+3.5*s),d=p*(L1+L2);dot(d<L1?cx:cx-(d-L1),d<L1?sy+(cy-sy)*d/L1:cy,6,'#e05a5a');}}
 if(i===2){path([[20,150],[400,150]]);tower(200,80,'🏹');for(let k=0;k<3;k++){const p=((t*.2+k*.33)%1),ex=lerp(20,400,p);dot(ex,150,8,'#e05a5a');if(Math.abs(ex-200)<120&&((t*3+k)%1)<.5){c.strokeStyle='#ffd75a';c.lineWidth=2;c.beginPath();c.moveTo(200,80);c.lineTo(ex,150);c.stroke();}}c.strokeStyle='rgba(110,190,255,.6)';c.lineWidth=1.5;c.beginPath();c.arc(200,80,120,0,7);c.stroke();txt('Nv '+(1+Math.floor(t/2)%3),200,45,'#ffd75a');}
 if(i===3){path([[20,160],[400,160]]);c.fillStyle='#e0605a';c.fillRect(105,75,50,50);tower(130,100,'🏹');tower(290,100,'🏹');for(let k=0;k<3;k++){const p=((t*.2+k*.33)%1);dot(lerp(20,400,p),160,8,'#e05a5a');}if((t*1.2)%1<.25)txt('15',150,135,'#ff7a6e',18);if((t*2.4)%1<.3)txt('10',310,135,'#fff',13);txt('Potencia',130,55,'#e0605a',13);txt('Normal',290,55,'#c9ced8',13);}
 if(i===4){path([[20,110],[400,110]]);core(390,110);const hx=230;dot(hx,110,16,'#b8c4dd');txt('⚔️',hx,111,'#fff',14);c.font='20px sans-serif,"Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji"';c.fillText('🚩',hx,80);const p=Math.min(1,(t%3)/1.6);dot(lerp(20,hx-22,p),110,8,'#e05a5a');dot(lerp(20,hx-40,Math.max(0,p-.15)),110,8,'#e05a5a');if(p>=1)txt('¡Bloqueado!',hx,150,'#ffd75a',13);}
 if(i===5){const p=Math.min(1,(t%4)/2);path([[20,110],[lerp(60,300,p),110]]);c.font='34px sans-serif,"Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji"';c.textAlign='center';c.textBaseline='middle';c.fillText(p>=1?'🎁':'📦',330,110);if(p>=1){const q=Math.min(1,((t%4)-2)/.6);['🔭','📯','❄️'].forEach((ic,k)=>{c.globalAlpha=q;c.font='24px sans-serif,"Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji"';c.fillText(ic,330+(k-1)*45*q,60-20*q);c.globalAlpha=1;});}txt('?',120,40,'#c9a0ff',26);}
 if(i===6){path([[20,140],[400,140]]);const p=((t*.12)%1),ex=lerp(20,400,p);dot(ex,140,13,'#a04a7a');c.strokeStyle='#cfd5e0';c.lineWidth=3;c.beginPath();c.arc(ex,140,16,0,7);c.stroke();tower(120,70,'🏹');tower(300,70,'⚡','#c27aff');if((t*2)%1<.3)txt('4',ex-14,112,'#fff',12);if((t*1)%1<.35)txt('12',ex+14,108,'#c9a0ff',16);txt('Físico: la armadura lo reduce',120,30,'#d8d8d8',12);txt('Mágico: la ignora',300,30,'#c9a0ff',12);}
}
function startGame(n){SEEOK=true;saveClear();
 TUTON=false;
 if(n)MR=n;ROUNDS=MR;CHESTS=chestsFor(ROUNDS);setSize(mapFor(ROUNDS));$('menu').classList.remove('setup');
 if(TOUCH&&OPT.fs)enterFS();
 lbClose(false);
 document.body.classList.remove('inmenu');$('endscr').classList.remove('open');init();
}
// primera partida normal ganada: si aún no tenía a Radagast (se saltó el tutorial), lo desbloquea
function winRad(h0){let had=true;try{had=h0!==undefined?h0:radOk();localStorage.setItem('rt-win1','1');}catch(e){}if(!had&&!OPT.u_hr){STO.qrad=1;saveSto();delete HEROES.radagast.lockTxt;newU('hr',HEROES.radagast.ic,HEROES.radagast.n,'Primera partida ganada','radagast');}}
function endGame(){
 const st=S.st,won=S.phase==='won',H=S.hero,earned=st.gKill+st.gTile+st.gRound+st.gRel+(st.gEv||0);if(won){pigWin();if(!S.tut){/* antes de achWin: la victoria cuenta en HWIN y haría creer que Radagast ya estaba desbloqueado */const rh=radOk();achWin();storyWin();winRad(rh);}}if(won&&!S.tut&&S.list.some(t=>t.type==='sala')&&S.list.some(t=>t.type==='frost'))achieve('elem');
 const g=n=>`<span class="gd">${fi(n)} 🪙</span>`,d=n=>`<span class="cd">${fi(n)}</span>`;
 const all=st.all.slice().sort((a,b)=>(b.dmgT||0)-(a.dmgT||0));
 const hd=H?(H.pt.dmgT||0):0,tdm=all.reduce((s,t)=>s+(t.dmgT||0),0),other=Math.max(0,st.dmg-tdm-hd);
 const pc=v=>st.dmg>0?Math.round(v/st.dmg*100):0;
 const row=(en,ev,bar)=>`<div class="erow"><div class="en">${en}</div><div class="ev">${ev}</div>${bar!==undefined?`<div class="ebar"><span style="width:${Math.min(100,bar)}%"></span></div>`:''}</div>`;
 const sum=(l,v)=>`<div><small>${l}</small><b>${v}</b></div>`;
 let h=`<h2>${won?'🏆 ¡Victoria!':'💀 Derrota'}</h2><small>${won?'El jefe ha caído y la expedición ha sido un éxito.':'El núcleo ha caído.'}</small>`+
  '<div class="esum">'+sum('Rondas alcanzadas',S.round+' / '+ROUNDS)+(H?sum('Héroe',H.def.ic+' '+H.def.n+' · Nv '+H.lvl):'')+sum('Oro obtenido',g(earned))+
  sum('Enemigos eliminados',fi(st.kills))+sum('Daño total',d(st.dmg))+sum('Tiempo real',fClk(GT.r))+sum('Tiempo de combate',fClk(GT.c))+(st.retries?sum('Reintentos usados',st.retries):'')+(won?sum('Vida del núcleo',S.hp):'')+'</div>';
 h+='<div class="esec">Torres</div>';
 if(!all.length)h+='<small>No construiste ninguna torre.</small>';
 for(const t of all){const X=tinfo(t),a=t.act||0,dm=t.dmgT||0;
  h+=row(`${icOf(X)} <b>${X.n}</b> · Nv ${t.lvl}${t.sold?' <small>(vendida)</small>':''}<small>Ronda ${t.rd} · ${bj(t.kills||0)}</small>`,
   `<span>DPS <span class="cd">${a>0?fi(dm/a):0}</span></span><span>Daño <span class="cd">${fi(dm)}</span> (${pc(dm)}%)</span>`,pc(dm));}
 if(H){const dm=H.pt.dmgT||0;h+=row(`${H.def.ic} <b>${H.def.n}</b> · Nv ${H.lvl}<small>Héroe · ${bj(H.pt.kills||0)}</small>`,
   `<span>DPS <span class="cd">${H.pt.act>0?fi(dm/H.pt.act):0}</span></span><span>Daño <span class="cd">${fi(dm)}</span> (${pc(dm)}%)</span>`,pc(dm));}
 if(pc(other)>=1)h+=row('Otras fuentes<small>Explosiones de veneno, barricadas…</small>',`<span>Daño <span class="cd">${fi(other)}</span> (${pc(other)}%)</span>`,pc(other));
 const rt={coin:()=>`${g(st.gRel)} generado`,venom:r=>`≈ ${d(r.dmg)} de daño por veneno`,frost:r=>`${fi(r.n)} ralentizaciones · ${fi(r.n2)} congelados`,
  barricade:r=>`${fi(r.n)} enemigos detenidos`,compass:r=>`${fi(r.n)} desvíos`};
 h+='<div class="esec">Reliquias</div>';
 if(!S.relics.length)h+='<small>No tenías reliquias.</small>';
 for(const id of S.relics){const R=RELIC[id],r=RS(id);
  h+=row(`${R.ic} <b>${R.n}</b>`,`<span>${rt[id]?rt[id](r):`≈ ${d(r.dmg)} de daño aportado`}</span>`);}
 if(S.relics.length)h+='<small>El daño de las reliquias es una estimación: la parte del daño que no existiría sin ellas.</small>';
 h+='<div class="esec">Oro</div>'+row('Bajas',`<span>${g(st.gKill)}</span>`)+row('Fin de ronda',`<span>${g(st.gRound)}</span>`)+row('Casillas especiales',`<span>${g(st.gTile)}</span>`)+
  row('Reliquias',`<span>${g(st.gRel)}</span>`)+row('Eventos',`<span>${g(st.gEv||0)}</span>`)+row('<b>Total obtenido</b>',`<span>${g(earned)}</span>`)+row('Gastado en torres y mejoras',`<span>${g(st.spent)}</span>`)+row('Recuperado por ventas',`<span>${g(st.gSell)}</span>`);
 const rtw=!won&&S.snap&&S.rc>0;
 // el final de partida es el libro abierto: cifras a la izquierda, desglose a la derecha; volver abajo a la izquierda, seguir abajo a la derecha
 const i=h.indexOf('<div class="esec">');LB.end={won,left:h.slice(0,i),right:h.slice(i),
  footL:'<button class="lbbk" data-a="menu">‹ Menú principal</button><button class="lbbk" data-a="hideend">🗺️ Ver el mapa</button>',
  footR:(rtw?`<button class="lbbk" data-a="retry" data-now="1">↺ Reintentar oleada (${S.rc})</button>`:'')+'<button class="gbtn" data-a="reset">Jugar de nuevo ›</button>'};lbOpen('end');
}
